const geminiResponse = $('Request a Gemini').first().json; // confirmá el nombre real con autocompletado
const calculado = $('Calcular Diagnostico').first().json.diagnostico_calculado;
const cultivoData = $('Obtener lecturas y conocimiento').first().json;

let textoGemini;
try {
  const rawText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  textoGemini = JSON.parse(cleaned);
} catch (e) {
  textoGemini = { tendencia: 'desconocida', recomendaciones_preventivas: [], mensaje_agricultor: 'No se pudo generar el detalle (falla de IA), pero el sistema detectó nivel de alerta: ' + calculado.nivel_alerta };
}

const diagnostico = {
  estado_optimo: calculado.estado_optimo,
  nivel_alerta: calculado.nivel_alerta,
  desviaciones_leves: calculado.desviaciones.map(d => d.metrica),
  tendencia: textoGemini.tendencia || 'estable',
  recomendaciones_preventivas: textoGemini.recomendaciones_preventivas || [],
  mensaje_agricultor: textoGemini.mensaje_agricultor || ''
};

return [{ json: { ...cultivoData, diagnostico } }];

