const ideal = $('Conocimiento Experto').first().json; // de 'Conocimiento Experto': planta, etapa, humedad_min/max, ph_min/max, ideal_n/p/k
const promedios = $('Obtener lecturas y conocimiento').first().json; // humedad_promedio, ph_promedio, n_promedio, p_promedio, k_promedio

const UMBRAL_LEVE = 10;

function evaluarRango(valorActual, min, max) {
  if (valorActual == null) return { categoria: 'sin_dato', desviacion_pct: null };
  if (valorActual >= min && valorActual <= max) return { categoria: 'optimo', desviacion_pct: 0 };
  const anchoRango = max - min;
  const distancia = valorActual < min ? (min - valorActual) : (valorActual - max);
  const desviacion_pct = Math.round((distancia / anchoRango) * 1000) / 10;
  return { categoria: desviacion_pct <= UMBRAL_LEVE ? 'leve' : 'seria', desviacion_pct };
}

function evaluarIdeal(valorActual, idealValor) {
  if (valorActual == null || !idealValor) return { categoria: 'sin_dato', desviacion_pct: null };
  const desviacion_pct = Math.round((Math.abs(valorActual - idealValor) / idealValor) * 1000) / 10;
  return { categoria: desviacion_pct === 0 ? 'optimo' : (desviacion_pct <= UMBRAL_LEVE ? 'leve' : 'seria'), desviacion_pct };
}

const metricas = {
  humedad: { ...evaluarRango(promedios.humedad_promedio, ideal.humedad_min, ideal.humedad_max), actual: promedios.humedad_promedio, min: ideal.humedad_min, max: ideal.humedad_max },
  ph:      { ...evaluarRango(promedios.ph_promedio, ideal.ph_min, ideal.ph_max), actual: promedios.ph_promedio, min: ideal.ph_min, max: ideal.ph_max },
  n:       { ...evaluarIdeal(promedios.n_promedio, ideal.ideal_n), actual: promedios.n_promedio, ideal: ideal.ideal_n },
  p:       { ...evaluarIdeal(promedios.p_promedio, ideal.ideal_p), actual: promedios.p_promedio, ideal: ideal.ideal_p },
  k:       { ...evaluarIdeal(promedios.k_promedio, ideal.ideal_k), actual: promedios.k_promedio, ideal: ideal.ideal_k },
};

const categorias = Object.values(metricas).map(m => m.categoria);
const hayGrave = categorias.includes('seria');
const hayLeve = categorias.includes('leve');

const diagnostico_calculado = {
  estado_optimo: !hayGrave && !hayLeve,
  nivel_alerta: hayGrave ? 'seria' : (hayLeve ? 'leve' : 'optima'),
  metricas,
  desviaciones: Object.entries(metricas)
    .filter(([_, m]) => m.categoria === 'leve' || m.categoria === 'seria')
    .map(([nombre, m]) => ({ metrica: nombre, ...m }))
};

return [{ json: { ...ideal, ...promedios, diagnostico_calculado } }];
